559	            ),
560	          );
561	      }
562	
563	      try {
564	        await stopRuntimeServicesForExecutionWorkspace({
565	          db,
566	          executionWorkspaceId: existing.id,
567	          workspaceCwd: existing.cwd,
568	        });
569	        const projectWorkspace = existing.projectWorkspaceId
570	          ? await db
571	              .select({
572	                cwd: projectWorkspaces.cwd,
573	                cleanupCommand: projectWorkspaces.cleanupCommand,
574	              })
575	              .from(projectWorkspaces)
576	              .where(
577	                and(
578	                  eq(projectWorkspaces.id, existing.projectWorkspaceId),
579	                  eq(projectWorkspaces.companyId, existing.companyId),
580	                ),
581	              )
582	              .then((rows) => rows[0] ?? null)
583	          : null;
584	        const projectPolicy = existing.projectId
585	          ? await db
586	              .select({
587	                executionWorkspacePolicy: projects.executionWorkspacePolicy,
588	              })
589	              .from(projects)
590	              .where(and(eq(projects.id, existing.projectId), eq(projects.companyId, existing.companyId)))
591	              .then((rows) => parseProjectExecutionWorkspacePolicy(rows[0]?.executionWorkspacePolicy))
592	          : null;
593	        const cleanupResult = await cleanupExecutionWorkspaceArtifacts({
594	          workspace: existing,
595	          projectWorkspace,
596	          teardownCommand: configForCleanup?.teardownCommand ?? projectPolicy?.workspaceStrategy?.teardownCommand ?? null,
597	          cleanupCommand: configForCleanup?.cleanupCommand ?? null,
598	          recorder: workspaceOperationsSvc.createRecorder({
599	            companyId: existing.companyId,
600	            executionWorkspaceId: existing.id,
601	          }),
602	        });
603	        cleanupWarnings = cleanupResult.warnings;
604	        const cleanupPatch: Record<string, unknown> = {
605	          closedAt,
606	          cleanupReason: cleanupWarnings.length > 0 ? cleanupWarnings.join(" | ") : null,
607	        };
608	        if (!cleanupResult.cleaned) {
609	          cleanupPatch.status = "cleanup_failed";
610	        }
611	        if (cleanupResult.warnings.length > 0 || !cleanupResult.cleaned) {
612	          workspace = (await svc.update(id, cleanupPatch)) ?? workspace;
613	        }
614	      } catch (error) {
615	        const failureReason = error instanceof Error ? error.message : String(error);
616	        workspace =
617	          (await svc.update(id, {
618	            status: "cleanup_failed",
619	            closedAt,
620	            cleanupReason: failureReason,
621	          })) ?? workspace;
622	        return Response.json({
623	          error: `Failed to archive execution workspace: ${failureReason}`,
624	        }, { status: 500 });
625	      }
626	    } else {
627	      const updatedWorkspace = await svc.update(id, patch);
628	      if (!updatedWorkspace) {
629	        return Response.json({ error: "Execution workspace not found" }, { status: 404 });
630	      }
631	      workspace = updatedWorkspace;
